window.MG_LAZY_DATA["data/lazy/courses/a106-e5e2c1ee304d0319.json"]={sha256:"e5e2c1ee304d03197806c920157f1fa2e2a5e461271b67a143027fedd5f4abf7",value:{"id":"a106","title":"晶圓對晶圓混合接合","titleEn":"Wafer-to-wafer hybrid bonding","category":"packaging","kind":"course","summary":"36 項任務深入 W2W 混合接合：保留原 12 步，再以配對良率、二維對位、CMP 形貌、污染統計、熱機相容、Kelvin 電阻、串鏈與資格證據完成設計審查。","summaryEn":"Thirty-six W2W hybrid-bonding tasks preserve the original twelve and add pairing yield, 2D overlay, CMP topography, contamination statistics, thermomechanical compatibility, Kelvin resistance, chains and qualification evidence.","sourceIds":["v6-hybrid-evg","v6-hybrid-imec","v9a-imecd2w","v9deep-thermal-stress","v9deep-w2w-2026","pkb-tsmc-soic","v9-media-3363c0f741d8","v10-media-14f744acab6a"],"status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"stepCount":36,"estimatedMinutes":840,"languageCoverage":["zh-TW","en"],"diagram":{"type":"package","labels":["晶圓配對","表面整備","對位","混合接合","可靠度"],"labelsEn":["Wafer pairing","Surface preparation","Alignment","Hybrid bond","Reliability"],"original":true,"notToScale":true},"stages":[{"id":"a106-stage01","order":1,"title":"界面與版圖","titleEn":"Interface and layout","description":"先界定成對晶圓、接點與驗證結構。","descriptionEn":"Define the paired wafers, contacts and verification structures.","steps":[{"id":"a106-v6-01","order":1,"sequence":1,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-evg","v6-hybrid-imec"],"prerequisiteIds":[],"title":"界定混合接合的兩種功能","titleEn":"Define the two functions of hybrid bonding","objective":"區別介電層支撐與金屬導通。","objectiveEn":"Distinguish dielectric attachment from metal conduction.","instruction":"畫出兩片面對面的截面，將介電層接觸與銅接墊接觸分色。追蹤一條訊號跨越界面的路徑，指出哪些位置負責支撐、哪些位置必須導通。","instructionEn":"Draw face-to-face sections and color dielectric and copper contacts separately. Trace one signal across the interface, identifying mechanical attachment and required electrical continuity.","observation":"整片看似貼合，並不表示每個銅接點已導通。","observationEn":"Apparent full-area attachment does not prove continuity through every copper contact.","failure":"若把介電層畫成導線，重新檢查電流路徑與材料標記。","failureEn":"If dielectric is drawn as a wire, revisit the current path and material labels.","check":"分別指定機械接合與電性接點的驗證方法。","checkEn":"Assign separate verification approaches to attachment and electrical contacts.","knowledge":[{"id":"a106-v6-01-k1","title":"雙重界面","titleEn":"A dual interface","text":"混合接合把介電層連接與嵌入金屬互連結合在同一界面。","textEn":"Hybrid bonding combines dielectric attachment and embedded metal interconnects at one interface."},{"id":"a106-v6-01-k2","title":"功能分驗","titleEn":"Separate functional evidence","text":"機械完整與電性導通互相關聯，但不能互相替代驗證。","textEn":"Mechanical integrity and electrical continuity are related but need separate evidence."}],"quiz":{"question":"看見整片沒有分離，能證明什麼？","questionEn":"What does observing that the wafers remain attached establish?","options":["提供機械貼合的部分證據，仍須電性驗證。","介電貼合強度已足以代表所有接觸電阻。","只要外圓重合，就證明每一接墊的隔離合格。"],"optionsEn":["It provides some attachment evidence; electrical verification remains necessary.","Dielectric attachment strength fully represents every contact resistance.","Overlapping outlines prove isolation of every pad."],"answer":0,"explanation":"提供機械貼合的部分證據，仍須電性驗證。 混合接合把介電層連接與嵌入金屬互連結合在同一界面。","explanationEn":"It provides some attachment evidence; electrical verification remains necessary. Hybrid bonding combines dielectric attachment and embedded metal interconnects at one interface."}},{"id":"a106-v6-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-evg","v6-hybrid-imec"],"prerequisiteIds":["a106-v6-01"],"title":"核對成對晶圓的版圖與方位","titleEn":"Check paired layouts and orientation","objective":"避免面對面翻轉造成接點配對錯誤。","objectiveEn":"Prevent contact mismatches caused by face-to-face reversal.","instruction":"在透明紙或繪圖軟體畫兩片含不對稱記號的晶圓。將上片翻面，逐一對應接墊與方向標記，再比較旋轉與鏡射的差異。","instructionEn":"Draw two wafers with asymmetric marks on transparent sheets or in drawing software. Flip the upper wafer and match pads and orientation marks, comparing rotation with reflection.","observation":"對稱圖案可能掩蓋翻面錯誤，因此保留不對稱檢查點。","observationEn":"Symmetric patterns can hide a reversal error, so retain an asymmetric check.","failure":"只對齊外圓卻錯配接墊時，應回到座標轉換，而非微調所有接點。","failureEn":"If wafer outlines align but pads mismatch, revisit coordinate transforms rather than adjust every contact.","check":"用三個非共線標記驗證方向，並說明翻面後的接點對應。","checkEn":"Verify orientation with three non-collinear marks and explain pad correspondence after flipping.","knowledge":[{"id":"a106-v6-02-k1","title":"座標轉換","titleEn":"Coordinate transformation","text":"面對面接合需要一致的翻面、旋轉與位移定義。","textEn":"Face-to-face bonding needs consistent definitions of reflection, rotation and translation."},{"id":"a106-v6-02-k2","title":"不對稱標記","titleEn":"Asymmetric marks","text":"不對稱資訊能區分看似相同的錯誤方位。","textEn":"Asymmetric information distinguishes otherwise similar incorrect orientations."}],"quiz":{"question":"外圓重合但不對稱標記相反，優先檢查什麼？","questionEn":"Outlines overlap but asymmetric marks reverse. What should be checked first?","options":["只調整同一平移量，不檢查是否鏡射。","翻面與座標對應規則。","只看晶圓外圓，因為圖案方位不影響接點對應。"],"optionsEn":["Apply one translation without checking for reflection.","The flip and coordinate-mapping rules.","Inspect the wafer outline only, assuming pattern orientation cannot affect matching."],"answer":1,"explanation":"翻面與座標對應規則。 面對面接合需要一致的翻面、旋轉與位移定義。","explanationEn":"The flip and coordinate-mapping rules. Face-to-face bonding needs consistent definitions of reflection, rotation and translation."}},{"id":"a106-v6-03","order":3,"sequence":3,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec"],"prerequisiteIds":["a106-v6-02"],"title":"比較接墊尺寸與容許偏移","titleEn":"Compare pad size and overlay allowance","objective":"理解接觸重疊與相鄰間距的共同限制。","objectiveEn":"Understand joint limits from contact overlap and neighbor spacing.","instruction":"畫一組等尺寸接墊與一組上下不同尺寸接墊，逐次平移上層透明圖。記錄何時重疊不足或接近鄰點；所有尺寸自行假設，不能套用為製造規格。","instructionEn":"Draw equal-size and unequal-size pad pairs and translate the upper overlay. Record loss of overlap or approach to a neighbor; label all dimensions hypothetical, not manufacturing specifications.","observation":"增加接墊大小可改善部分重疊，但也會改變相鄰間距。","observationEn":"Enlarging a pad can improve overlap while changing neighbor clearance.","failure":"只最大化重疊而忽略鄰近接點，可能隱藏短路或介電風險。","failureEn":"Maximizing overlap while ignoring neighbors can conceal shorting or dielectric risk.","check":"同時呈現重疊與間距兩項判據，並指出適用的偏移方向。","checkEn":"Show both overlap and clearance criteria and identify the displacement directions considered.","knowledge":[{"id":"a106-v6-03-k1","title":"版圖容差","titleEn":"Layout tolerance","text":"接墊形狀與相對尺寸會改變對位誤差的容忍度。","textEn":"Pad geometry and relative size affect tolerance to alignment error."},{"id":"a106-v6-03-k2","title":"局部代價","titleEn":"Local trade-off","text":"幾何上的改良須連同鄰點間距和電性一起評估。","textEn":"A geometric improvement must be assessed with neighbor spacing and electrical behavior."}],"quiz":{"question":"為何不能無限制放大所有接墊？","questionEn":"Why not enlarge every pad without limit?","options":["接墊加大只會改善重疊，不影響鄰近間距。","只要銅面積增加，就不需考慮介電隔離。","重疊改善可能消耗鄰點間距。"],"optionsEn":["Enlarging pads improves overlap without affecting neighbor spacing.","More copper area removes the need to consider dielectric isolation.","Improved overlap can consume neighbor clearance."],"answer":2,"explanation":"重疊改善可能消耗鄰點間距。 接墊形狀與相對尺寸會改變對位誤差的容忍度。","explanationEn":"Improved overlap can consume neighbor clearance. Pad geometry and relative size affect tolerance to alignment error."}},{"id":"a106-v6-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec"],"prerequisiteIds":["a106-v6-03"],"title":"配置串鏈與隔離測試結構","titleEn":"Plan chain and isolation test structures","objective":"讓開路與相鄰漏電能被分開發現。","objectiveEn":"Make opens and neighbor leakage separately observable.","instruction":"在示意版圖串接多個跨界面接點，另畫相鄰但不相連的導體。預測單一開路、接觸電阻增加及鄰點短路，各會改變哪項測試結果。","instructionEn":"Chain multiple cross-interface contacts in a schematic and draw separate adjacent conductors. Predict which measurements change for an open, higher contact resistance or a neighbor short.","observation":"串鏈只顯示累積路徑，未必能定位單一異常接點。","observationEn":"A chain exposes a cumulative path but may not localize one defective contact.","failure":"把低串鏈電阻當作隔離合格會漏掉另一種故障；保留獨立隔離判據。","failureEn":"Treating low chain resistance as proof of isolation misses another failure class; retain a separate criterion.","check":"建立故障、測試結構與可見現象的三欄對照。","checkEn":"Map each fault to a test structure and observable response.","knowledge":[{"id":"a106-v6-04-k1","title":"可觀測性","titleEn":"Observability","text":"測試結構必須讓想找的失效改變可讀取的量。","textEn":"A test structure must make the targeted failure affect an observable quantity."},{"id":"a106-v6-04-k2","title":"累積與定位","titleEn":"Aggregation and localization","text":"整條串鏈的結果與單一接點的結果具有不同解析度。","textEn":"Whole-chain and individual-contact results have different diagnostic resolution."}],"quiz":{"question":"串鏈可導通，還需要哪類補充證據？","questionEn":"A chain conducts. What complementary evidence is still useful?","options":["相鄰導體的隔離與漏電檢查。","只重複同一串鏈讀值，不需要不同測試結構。","只檢查機械接合強度便能排除相鄰短路。"],"optionsEn":["Isolation and leakage checks between neighboring conductors.","Repeat the same chain reading; different test structures are unnecessary.","Mechanical bond strength alone rules out neighbor shorts."],"answer":0,"explanation":"相鄰導體的隔離與漏電檢查。 測試結構必須讓想找的失效改變可讀取的量。","explanationEn":"Isolation and leakage checks between neighboring conductors. A test structure must make the targeted failure affect an observable quantity."}}]},{"id":"a106-stage02","order":2,"title":"表面與對位","titleEn":"Surface and alignment","description":"區分表面幾何、表面狀態與面內對位的限制。","descriptionEn":"Separate limits from surface geometry, surface condition and in-plane alignment.","steps":[{"id":"a106-v6-05","order":1,"sequence":5,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v6-04"],"title":"判讀 CMP 後的銅凹陷與介電平坦度","titleEn":"Interpret copper recess and dielectric flatness","objective":"分開比較銅高度與介電面形貌。","objectiveEn":"Compare copper height separately from dielectric topography.","instruction":"畫出銅突出、合適凹陷及過深凹陷三種假想截面，標出首先接觸的位置。比較它們對介電貼合與後續金屬連接的影響，不設定通用奈米公差。","instructionEn":"Draw hypothetical protruding, appropriately recessed and deeply recessed copper sections. Mark first-contact locations and compare dielectric attachment and later metal connection without assigning universal nanometer tolerances.","observation":"全片平均平坦仍可能掩蓋某些接墊的局部高度問題。","observationEn":"Good average flatness can still hide local pad-height problems.","failure":"把所有材料畫成完全齊平，可能遺失研究流程所需的受控凹陷；回查來源路線。","failureEn":"Drawing every material perfectly flush can erase the controlled recess required by the referenced route; review its assumptions.","check":"說明三種截面的不同風險，且將量產公差保留為待查規格。","checkEn":"Explain the distinct risks and leave production tolerances as requirements to obtain.","knowledge":[{"id":"a106-v6-05-k1","title":"受控形貌","titleEn":"Controlled topography","text":"接合前形貌須同時配合介電接觸及後續銅連接。","textEn":"Prebond topography must accommodate both dielectric contact and subsequent copper connection."},{"id":"a106-v6-05-k2","title":"局部高度","titleEn":"Local height","text":"銅凹陷相對於鄰近介電面定義，不能只看晶圓平均厚度。","textEn":"Copper recess is relative to nearby dielectric, not merely average wafer thickness."}],"quiz":{"question":"銅凹陷應相對於哪個基準判讀？","questionEn":"What reference defines copper recess?","options":["整片晶圓背面的平均平面。","相鄰介電表面。","尚未拋光前的總銅沉積厚度。"],"optionsEn":["The average plane of the wafer backside.","The adjacent dielectric surface.","Total copper thickness before polishing."],"answer":1,"explanation":"相鄰介電表面。 接合前形貌須同時配合介電接觸及後續銅連接。","explanationEn":"The adjacent dielectric surface. Prebond topography must accommodate both dielectric contact and subsequent copper connection."}},{"id":"a106-v6-06","order":2,"sequence":6,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-evg","v6-hybrid-imec"],"prerequisiteIds":["a106-v6-05"],"title":"追溯清潔、活化與等待時間","titleEn":"Trace cleaning, activation and waiting","objective":"將表面狀態與後續接合條件連接。","objectiveEn":"Connect surface condition to subsequent bonding conditions.","instruction":"建立清潔、表面活化、等待與接合的時間線，為兩條假設路徑標記暴露及搬運點。比較粒子控制與活化目的，不推定兩者可互相取代。","instructionEn":"Build timelines for cleaning, activation, waiting and bonding, marking exposure and handling in two hypothetical routes. Compare particle control with activation without treating them as interchangeable.","observation":"兩片幾何相同的表面，仍可能因狀態或污染不同而表現不同。","observationEn":"Geometrically similar surfaces can behave differently because of condition or contamination.","failure":"缺少交接時間紀錄時，不能把不良全歸因於對位。","failureEn":"Without handoff timing records, do not attribute all failures to overlay.","check":"時間線包含每次表面暴露與可追溯的狀態紀錄。","checkEn":"Include each exposure and a traceable surface-condition record.","knowledge":[{"id":"a106-v6-06-k1","title":"表面功能","titleEn":"Surface functionality","text":"介電層直接接合依賴適當的表面狀態，不只是兩片相碰。","textEn":"Direct dielectric bonding depends on suitable surface condition, not merely physical contact."},{"id":"a106-v6-06-k2","title":"交接窗口","titleEn":"Handoff window","text":"等待和搬運也是流程條件，應與清潔及活化一起記錄。","textEn":"Waiting and handling are process conditions that belong with cleaning and activation records."}],"quiz":{"question":"活化後延長等待，為何仍需重新核對接合條件？","questionEn":"Why review bonding conditions after a longer post-activation wait?","options":["只要對位精度相同，表面暴露時間就不影響判定。","等待越久必然接合越強，不需檢查表面狀態。","表面狀態和暴露歷程可能改變。"],"optionsEn":["Equal overlay accuracy makes surface-exposure time irrelevant.","A longer wait always strengthens bonding without checking surface condition.","Surface condition and exposure history may change."],"answer":2,"explanation":"表面狀態和暴露歷程可能改變。 介電層直接接合依賴適當的表面狀態，不只是兩片相碰。","explanationEn":"Surface condition and exposure history may change. Direct dielectric bonding depends on suitable surface condition, not merely physical contact."}},{"id":"a106-v6-07","order":3,"sequence":7,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec"],"prerequisiteIds":["a106-v6-06"],"title":"分離平移、旋轉與變形誤差","titleEn":"Separate translation, rotation and distortion","objective":"用多位置標記判斷對位誤差模式。","objectiveEn":"Diagnose overlay-error patterns from multiple marks.","instruction":"在中心與四個外圍位置畫誤差箭頭，分別建立同向、繞中心旋轉及局部不規則三個案例。嘗試以一個平移修正各案例，觀察哪些殘差無法消除。","instructionEn":"Draw overlay vectors at the center and four outer positions for translation, rotation and irregular local distortion. Apply one translation correction to each and identify residuals it cannot remove.","observation":"中心對好仍可能在邊緣有旋轉或形變殘差。","observationEn":"Good center alignment can coexist with rotational or distortion residuals at the edge.","failure":"只用單一標記決定全片合格會忽略誤差模式；增加空間取樣。","failureEn":"One-mark acceptance overlooks error structure; add spatial sampling.","check":"將每種誤差對應到可修正部分與待調查部分。","checkEn":"Distinguish correctable components from residuals requiring investigation.","knowledge":[{"id":"a106-v6-07-k1","title":"誤差場","titleEn":"Error field","text":"對位是一個空間分布，不只是單一偏移值。","textEn":"Overlay is a spatial field, not just one offset."},{"id":"a106-v6-07-k2","title":"剛體限制","titleEn":"Rigid-body limits","text":"平移與旋轉不能完全補償所有局部變形。","textEn":"Translation and rotation cannot fully compensate every local distortion."}],"quiz":{"question":"平移後中心已對齊但邊緣仍繞中心偏轉，較像哪種誤差？","questionEn":"Translation fixes the center but edge vectors remain rotational. What does this suggest?","options":["仍有旋轉分量。","單純固定方向的平移，中心結果足以代表全片。","一定是所有接墊同等加寬，無需檢查對位模型。"],"optionsEn":["A remaining rotational component.","Pure fixed-direction translation, with center results representing the entire wafer.","Every pad must have widened equally, requiring no alignment-model review."],"answer":0,"explanation":"仍有旋轉分量。 對位是一個空間分布，不只是單一偏移值。","explanationEn":"A remaining rotational component. Overlay is a spatial field, not just one offset."}},{"id":"a106-v6-08","order":4,"sequence":8,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-evg","v6-hybrid-imec"],"prerequisiteIds":["a106-v6-07"],"title":"規劃接合前的雙面放行","titleEn":"Plan a two-surface prebond review","objective":"防止只檢查其中一片晶圓。","objectiveEn":"Avoid checking only one member of the wafer pair.","instruction":"為上下晶圓各建一張表，列出身分、方位、形貌、污染與等待歷程。挑選一項缺失資料，討論它如何影響整對晶圓的放行，而非以另一片的結果補值。","instructionEn":"Make separate records for wafer identity, orientation, topography, contamination and waiting history. Remove one item and explain how that affects pair release rather than substituting the other wafer’s result.","observation":"接合是成對事件，單片合格不等於配對與界面均合格。","observationEn":"Bonding is a paired event; one acceptable wafer does not prove a valid pair or interface.","failure":"批次或方位配對錯誤不能靠後段退火修正。","failureEn":"Annealing cannot repair an incorrect lot or orientation pairing.","check":"放行表可從接合批次追溯到兩片來料及各自量測。","checkEn":"Trace the bonded lot to both incoming wafers and their individual measurements.","knowledge":[{"id":"a106-v6-08-k1","title":"配對追溯","titleEn":"Pair traceability","text":"兩側輸入共同決定接合界面品質。","textEn":"Both inputs jointly determine interface quality."},{"id":"a106-v6-08-k2","title":"缺值處理","titleEn":"Handling missing evidence","text":"另一片的好結果不能補足本片缺少的證據。","textEn":"A good result from one wafer cannot fill an evidence gap for the other."}],"quiz":{"question":"上片形貌合格、下片未量測，正確結論為何？","questionEn":"The upper wafer passes topography checks but the lower is unmeasured. What follows?","options":["下片可沿用上片結果，因為兩片目標規格相同。","整對晶圓仍待驗證。","對位設備型號相同，就不需要下片形貌證據。"],"optionsEn":["The lower wafer can inherit the upper result because target specifications match.","The pair remains unverified.","The same aligner model removes the need for lower-wafer topography evidence."],"answer":1,"explanation":"整對晶圓仍待驗證。 兩側輸入共同決定接合界面品質。","explanationEn":"The pair remains unverified. Both inputs jointly determine interface quality."}}]},{"id":"a106-stage03","order":3,"title":"接合與驗證","titleEn":"Bonding and verification","description":"結合機械、空洞與電性證據，避免只用外觀判定接合成功。","descriptionEn":"Combine mechanical, void and electrical evidence rather than judge a bond by appearance.","steps":[{"id":"a106-v6-09","order":1,"sequence":9,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v6-08"],"title":"觀察接合波與未接合區域","titleEn":"Observe the bond wave and unbonded regions","objective":"把接觸傳播與空洞證據連結。","objectiveEn":"Relate contact propagation to void evidence.","instruction":"在原創示意圖畫出由起始接觸點擴展的接合前緣，再加入一個粒子與一個局部形貌障礙。預測可能留下的未接合區，與來源影像中的觀察方法比較。","instructionEn":"Draw an original bond front spreading from initial contact, then add one particle and one local topographic obstacle. Predict unbonded regions and compare the observation approach with referenced imagery.","observation":"前緣通過與界面完全無空洞是不同判斷。","observationEn":"Passage of a bond front is not the same conclusion as a void-free interface.","failure":"若只保存最終外觀，可能缺少判斷缺陷起源的時間資訊。","failureEn":"Keeping only the final appearance may lose timing needed to diagnose defect origins.","check":"標記預測區域、可檢查的方法及不能由示意圖證明的部分。","checkEn":"Mark predicted regions, an inspection approach and what the schematic cannot prove.","knowledge":[{"id":"a106-v6-09-k1","title":"接觸傳播","titleEn":"Contact propagation","text":"表面接觸可沿界面擴展，局部障礙會影響完整貼合。","textEn":"Contact can propagate along the interface, while local obstacles affect complete attachment."},{"id":"a106-v6-09-k2","title":"空洞定位","titleEn":"Void localization","text":"缺陷位置需與前處理和形貌紀錄交叉比較。","textEn":"Defect locations should be compared with preparation and topography records."}],"quiz":{"question":"模型顯示接合前緣已到邊緣，仍需檢查什麼？","questionEn":"The modeled bond front reaches the edge. What still needs checking?","options":["只需確認接觸前緣速度，無需檢查內部區域。","只量測外圓厚度，就可取代界面檢查。","界面內是否殘留未接合區。"],"optionsEn":["Only bond-front speed needs checking, not interior regions.","Edge thickness alone replaces interface inspection.","Whether unbonded regions remain inside the interface."],"answer":2,"explanation":"界面內是否殘留未接合區。 表面接觸可沿界面擴展，局部障礙會影響完整貼合。","explanationEn":"Whether unbonded regions remain inside the interface. Contact can propagate along the interface, while local obstacles affect complete attachment."}},{"id":"a106-v6-10","order":2,"sequence":10,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-evg","v6-hybrid-imec"],"prerequisiteIds":["a106-v6-09"],"title":"判讀退火對介電層與銅連接的作用","titleEn":"Interpret annealing of dielectric and copper bonds","objective":"區分初始貼合與後續接合強化。","objectiveEn":"Distinguish initial attachment from subsequent bond strengthening.","instruction":"用前後兩張截面圖標出預接合與退火後狀態，分別追蹤介電界面及銅接點。列出需向實際製程取得的熱預算與材料相容性資料，不填入通用溫度配方。","instructionEn":"Compare prebond and post-anneal sections, following dielectric interfaces and copper contacts separately. List thermal-budget and compatibility information needed from the actual process without inventing a universal temperature recipe.","observation":"某條研究路線的可用條件不代表所有介電材料與金屬堆疊皆適用。","observationEn":"Conditions demonstrated for one research route do not apply automatically to every dielectric and metal stack.","failure":"用提高溫度補償未知污染，可能增加其他損害而未處理根因。","failureEn":"Raising temperature to compensate for unknown contamination may add damage without addressing the cause.","check":"說明退火前後需要不同證據，並保留產品熱限制。","checkEn":"Explain the evidence needed before and after annealing and retain product thermal constraints.","knowledge":[{"id":"a106-v6-10-k1","title":"接合演變","titleEn":"Bond evolution","text":"初始貼合與永久介電、金屬接合的形成是不同階段。","textEn":"Initial attachment and development of permanent dielectric and metal bonds are distinct stages."},{"id":"a106-v6-10-k2","title":"熱預算相容性","titleEn":"Thermal-budget compatibility","text":"接合條件須與先前完成的元件和互連相容。","textEn":"Bonding conditions must remain compatible with existing devices and interconnects."}],"quiz":{"question":"能否把研究文章中的退火條件直接當所有產品配方？","questionEn":"Can an article’s anneal condition become the recipe for every product?","options":["不能，材料、堆疊與熱預算需分別核對。","能，只要研究和產品使用相同晶圓直徑。","能，所有既有互連對接合熱歷程的承受能力相同。"],"optionsEn":["No; materials, stacks and thermal budgets need separate review.","Yes, if research and product wafer diameters match.","Yes; all existing interconnects tolerate the same bonding thermal history."],"answer":0,"explanation":"不能，材料、堆疊與熱預算需分別核對。 初始貼合與永久介電、金屬接合的形成是不同階段。","explanationEn":"No; materials, stacks and thermal budgets need separate review. Initial attachment and development of permanent dielectric and metal bonds are distinct stages."}},{"id":"a106-v6-11","order":3,"sequence":11,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec"],"prerequisiteIds":["a106-v6-10"],"title":"交叉判讀空洞、串鏈與接點電阻","titleEn":"Cross-check voids, chains and contact resistance","objective":"避免單一測試掩蓋不同失效模式。","objectiveEn":"Avoid allowing one test to conceal other failure modes.","instruction":"製作四個紙上案例：外觀正常但串鏈開路、可導通但局部空洞、阻值偏高及各項一致。為每例選擇下一個能縮小原因範圍的量測，而非立即重工。","instructionEn":"Create paper cases with a normal appearance but open chain, conduction with local voids, elevated resistance and consistent results. Choose the next discriminating measurement before proposing rework.","observation":"不同證據可能互補，也可能揭露取樣範圍不一致。","observationEn":"Different evidence can complement itself or reveal inconsistent sampling coverage.","failure":"若把測到一條好串鏈擴大成整片合格，需回查測試覆蓋率。","failureEn":"If one good chain becomes a claim about the entire wafer, revisit coverage.","check":"每個異常結論均指出測試覆蓋範圍及尚未排除的原因。","checkEn":"State test coverage and remaining possible causes for every abnormal conclusion.","knowledge":[{"id":"a106-v6-11-k1","title":"多物理驗證","titleEn":"Multiphysics verification","text":"機械界面與電性路徑需要交叉驗證，才能縮小失效原因。","textEn":"Mechanical interface and electrical-path evidence must be combined to narrow causes."},{"id":"a106-v6-11-k2","title":"取樣覆蓋","titleEn":"Sampling coverage","text":"局部良好結果不等於未量測區域已被證明良好。","textEn":"A good local result does not establish the condition of unmeasured regions."}],"quiz":{"question":"一條串鏈正常但附近影像有空洞，最佳解讀是什麼？","questionEn":"One chain passes but nearby imaging shows a void. What is the best interpretation?","options":["串鏈導通已足以排除所有機械界面缺陷。","兩種測試覆蓋與失效敏感性不同，需交叉定位。","有局部空洞便可認定整片每個接點都開路。"],"optionsEn":["Chain continuity rules out every mechanical-interface defect.","Coverage and failure sensitivity differ; correlate their locations.","One local void proves every wafer contact is open."],"answer":1,"explanation":"兩種測試覆蓋與失效敏感性不同，需交叉定位。 機械界面與電性路徑需要交叉驗證，才能縮小失效原因。","explanationEn":"Coverage and failure sensitivity differ; correlate their locations. Mechanical interface and electrical-path evidence must be combined to narrow causes."}},{"id":"a106-v6-12","order":4,"sequence":12,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v6-11"],"title":"建立接合批次的可靠度與交接表","titleEn":"Build a bond-lot reliability handoff","objective":"將製程條件、初始結果與後續變化連在一起。","objectiveEn":"Link process conditions, initial results and later changes.","instruction":"把配對識別、對位地圖、形貌、接合紀錄及初始電性放入一張交接表。再加入假設的應力前後結果，區分初始缺陷和隨時間出現的劣化。","instructionEn":"Combine pairing, overlay, topography, bond history and initial electrical results in a handoff sheet. Add hypothetical before-and-after stress results to distinguish initial defects from later degradation.","observation":"初始可導通不代表經應力後仍維持相同表現。","observationEn":"Initial continuity does not guarantee unchanged behavior after stress.","failure":"沒有初始基線便難以判斷變化；先補足基線與樣本對應。","failureEn":"Without a baseline, change is hard to judge; restore baseline and sample correspondence.","check":"為放行、複查與後續可靠度驗證各列出條件，不宣稱教學模型已證明量產可靠度。","checkEn":"Define release, review and later reliability conditions without claiming that the teaching model proves production reliability.","knowledge":[{"id":"a106-v6-12-k1","title":"基線比較","titleEn":"Baseline comparison","text":"可靠度觀察需要把同一樣本的初始與後續證據連接。","textEn":"Reliability observations need a link between the same sample’s initial and later evidence."},{"id":"a106-v6-12-k2","title":"工程交接","titleEn":"Engineering handoff","text":"後段薄化、互連與測試需知道接合界面的限制與未解問題。","textEn":"Later thinning, interconnect and test operations need interface limits and unresolved issues."}],"quiz":{"question":"為何保留應力測試前的電性基線？","questionEn":"Why retain electrical results from before a stress test?","options":["用基線直接代替所有應力後量測。","只比較不同批次的最終平均值，不追蹤同一樣本。","用來識別後續變化，而不只看最終數字。"],"optionsEn":["Substitute the baseline for every post-stress measurement.","Compare only final averages from different lots without tracking the same sample.","To identify change rather than view only a final number."],"answer":2,"explanation":"用來識別後續變化，而不只看最終數字。 可靠度觀察需要把同一樣本的初始與後續證據連接。","explanationEn":"To identify change rather than view only a final number. Reliability observations need a link between the same sample’s initial and later evidence."}}]},{"id":"a106-v9-stage04","order":4,"sequence":4,"title":"配對良率與二維對位","titleEn":"Pairing yield and two-dimensional overlay","description":"六項原創工程推算與判讀任務。算例皆為明示假設，需保留單位、參考面、模型範圍與驗收證據。","descriptionEn":"Six authored calculation and interpretation tasks. Examples are explicitly hypothetical; retain units, reference planes, model limits and acceptance evidence.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"enrichmentVersion":9,"steps":[{"id":"a106-v9-013","order":1,"sequence":13,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"prerequisiteIds":["a106-v6-12"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"比較整片配對與良品晶粒組合","titleEn":"Compare wafer pairing and known-good-die assembly","objective":"同報地圖交集與獨立模型，指出兩者差異。","objectiveEn":"Report both map intersection and the independence model, explaining differences.","instruction":"畫兩張 4×4 良率地圖，對位後計算共同良品，再思考 D2W 可重配的範圍和限制。","instructionEn":"Draw two 4×4 yield maps, align them and count jointly good positions, then assess D2W remapping possibilities and constraints.","observation":"假設上下片每位置良率 90% 且獨立、接合存活率 98%，共同良品率=0.9²×0.98=79.38%；有空間相關時不能直接套用。","observationEn":"Assuming independent 90% die yield on each wafer and 98% bond survival gives 0.9²×0.98=79.38%; spatial correlation invalidates direct use.","failure":"忽略上下晶圓地圖相關性會使成本估算失真。","failureEn":"Ignoring cross-wafer map correlation distorts cost estimates.","check":"同報地圖交集與獨立模型，指出兩者差異。","checkEn":"Report both map intersection and the independence model, explaining differences.","knowledge":[{"id":"a106-v9-013-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"W2W 同時接合整片對應位置；D2W 可挑選晶粒，但增加切割、搬運與放置負擔。","textEn":"W2W bonds corresponding wafer positions together; D2W can select dies but adds singulation, handling and placement burdens.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"]},{"id":"a106-v9-013-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設上下片每位置良率 90% 且獨立、接合存活率 98%，共同良品率=0.9²×0.98=79.38%；有空間相關時不能直接套用。 驗收：同報地圖交集與獨立模型，指出兩者差異。","textEn":"Assuming independent 90% die yield on each wafer and 98% bond survival gives 0.9²×0.98=79.38%; spatial correlation invalidates direct use. Acceptance: Report both map intersection and the independence model, explaining differences."}],"quiz":{"question":"檢查「比較整片配對與良品晶粒組合」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Compare wafer pairing and known-good-die assembly\", which conclusion is supported?","options":["同報地圖交集與獨立模型，指出兩者差異。","90% 與 90% 配對後必為 90%。","D2W 挑良品不會增加任何搬運風險。"],"optionsEn":["Report both map intersection and the independence model, explaining differences.","Pairing two 90% wafers necessarily yields 90%.","D2W selection adds no handling risks."],"answer":0,"explanation":"假設上下片每位置良率 90% 且獨立、接合存活率 98%，共同良品率=0.9²×0.98=79.38%；有空間相關時不能直接套用。 忽略上下晶圓地圖相關性會使成本估算失真。","explanationEn":"Assuming independent 90% die yield on each wafer and 98% bond survival gives 0.9²×0.98=79.38%; spatial correlation invalidates direct use. Ignoring cross-wafer map correlation distorts cost estimates."}},{"id":"a106-v9-014","order":2,"sequence":14,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"prerequisiteIds":["a106-v9-013"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"將對位誤差表示為向量","titleEn":"Represent overlay as a vector","objective":"同報向量圖、偏置及半徑分布。","objectiveEn":"Report the vector map, bias and radial distribution.","instruction":"將各測點 dx、dy 畫成向量場，算 r=√(dx²+dy²)，區分平均偏置與殘差。","instructionEn":"Plot dx and dy as a vector field, calculate r=√(dx²+dy²), and separate mean bias from residuals.","observation":"假設 dx=30 nm、dy=40 nm，r=50 nm；兩個方向都小於 45 nm，仍不符合自訂 r≤45 nm。","observationEn":"Hypothetical dx=30 nm and dy=40 nm give r=50 nm; both axes are below 45 nm but fail an authored radial limit r≤45 nm.","failure":"只看平均向量接近零會掩蓋正負誤差相消。","failureEn":"A near-zero mean vector can hide cancellation of positive and negative errors.","check":"同報向量圖、偏置及半徑分布。","checkEn":"Report the vector map, bias and radial distribution.","knowledge":[{"id":"a106-v9-014-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"X/Y 誤差與徑向誤差有不同統計分布，不能把單軸門檻直接當二維半徑門檻。","textEn":"X/Y errors and radial error have different distributions; a one-axis limit is not a two-dimensional radial limit.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"]},{"id":"a106-v9-014-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 dx=30 nm、dy=40 nm，r=50 nm；兩個方向都小於 45 nm，仍不符合自訂 r≤45 nm。 驗收：同報向量圖、偏置及半徑分布。","textEn":"Hypothetical dx=30 nm and dy=40 nm give r=50 nm; both axes are below 45 nm but fail an authored radial limit r≤45 nm. Acceptance: Report the vector map, bias and radial distribution."}],"quiz":{"question":"檢查「將對位誤差表示為向量」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Represent overlay as a vector\", which conclusion is supported?","options":["兩軸各小於 45 nm 就保證半徑小於 45 nm。","同報向量圖、偏置及半徑分布。","平均零等於每點零誤差。"],"optionsEn":["Both axes below 45 nm guarantee radius below 45 nm.","Report the vector map, bias and radial distribution.","Zero mean implies zero error at every point."],"answer":1,"explanation":"假設 dx=30 nm、dy=40 nm，r=50 nm；兩個方向都小於 45 nm，仍不符合自訂 r≤45 nm。 只看平均向量接近零會掩蓋正負誤差相消。","explanationEn":"Hypothetical dx=30 nm and dy=40 nm give r=50 nm; both axes are below 45 nm but fail an authored radial limit r≤45 nm. A near-zero mean vector can hide cancellation of positive and negative errors."}},{"id":"a106-v9-015","order":3,"sequence":15,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"prerequisiteIds":["a106-v9-014"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"拆出旋轉造成的邊緣位移","titleEn":"Separate rotation-induced edge displacement","objective":"保留 θ 的弧度單位與邊緣預測值。","objectiveEn":"Retain θ in radians and predicted edge displacement.","instruction":"以中心和邊緣對位標記擬合旋轉，將剛體旋轉從向量場扣除再看局部殘差。","instructionEn":"Fit rotation using center and edge marks, subtract rigid rotation and inspect local residuals.","observation":"假設半徑 100 mm、旋轉 1 µrad，邊緣位移 100 nm；中心標記幾乎不動不能證明全片合格。","observationEn":"At hypothetical radius 100 mm and rotation 1 µrad, edge shift is 100 nm; a nearly fixed center does not prove whole-wafer compliance.","failure":"僅用中心標記校正會漏掉角度誤差。","failureEn":"Center-only alignment misses rotational error.","check":"保留 θ 的弧度單位與邊緣預測值。","checkEn":"Retain θ in radians and predicted edge displacement.","knowledge":[{"id":"a106-v9-015-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"小旋轉造成的切向位移約 rθ，距中心越遠越敏感。","textEn":"A small rotation causes tangential displacement approximately rθ, increasing away from the center.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"]},{"id":"a106-v9-015-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設半徑 100 mm、旋轉 1 µrad，邊緣位移 100 nm；中心標記幾乎不動不能證明全片合格。 驗收：保留 θ 的弧度單位與邊緣預測值。","textEn":"At hypothetical radius 100 mm and rotation 1 µrad, edge shift is 100 nm; a nearly fixed center does not prove whole-wafer compliance. Acceptance: Retain θ in radians and predicted edge displacement."}],"quiz":{"question":"檢查「拆出旋轉造成的邊緣位移」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Separate rotation-induced edge displacement\", which conclusion is supported?","options":["1 µrad 在所有半徑造成同樣位移。","中心對準即可免查邊緣。","保留 θ 的弧度單位與邊緣預測值。"],"optionsEn":["1 µrad produces equal displacement at every radius.","Center alignment removes the need to check edges.","Retain θ in radians and predicted edge displacement."],"answer":2,"explanation":"假設半徑 100 mm、旋轉 1 µrad，邊緣位移 100 nm；中心標記幾乎不動不能證明全片合格。 僅用中心標記校正會漏掉角度誤差。","explanationEn":"At hypothetical radius 100 mm and rotation 1 µrad, edge shift is 100 nm; a nearly fixed center does not prove whole-wafer compliance. Center-only alignment misses rotational error."}},{"id":"a106-v9-016","order":4,"sequence":16,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"prerequisiteIds":["a106-v9-015"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"區別倍率與局部變形","titleEn":"Distinguish scale error from local distortion","objective":"提交擬合係數與扣除後殘差。","objectiveEn":"Submit fitted coefficients and post-fit residuals.","instruction":"擬合平移、旋轉、倍率及正交項，再畫剩餘向量，保留未被模型描述的高階形變。","instructionEn":"Fit translation, rotation, scale and orthogonality, then plot residual vectors and retain higher-order distortion outside the model.","observation":"假設倍率差 1 ppm、r=100 mm，徑向差 100 nm；與 1 µrad 旋轉量級相同但方向不同。","observationEn":"A hypothetical 1 ppm scale mismatch at r=100 mm gives 100 nm radial error, comparable in magnitude to 1 µrad rotation but different in direction.","failure":"只報全片 RMS 無法區分可校正的倍率與局部缺陷。","failureEn":"Whole-wafer RMS alone cannot distinguish correctable scale from local defects.","check":"提交擬合係數與扣除後殘差。","checkEn":"Submit fitted coefficients and post-fit residuals.","knowledge":[{"id":"a106-v9-016-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"倍率誤差產生隨半徑增加的徑向位移；局部非線性變形無法靠一個平移完全修正。","textEn":"Scale error produces radial displacement increasing with radius; local nonlinear distortion cannot be removed by one translation.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"]},{"id":"a106-v9-016-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設倍率差 1 ppm、r=100 mm，徑向差 100 nm；與 1 µrad 旋轉量級相同但方向不同。 驗收：提交擬合係數與扣除後殘差。","textEn":"A hypothetical 1 ppm scale mismatch at r=100 mm gives 100 nm radial error, comparable in magnitude to 1 µrad rotation but different in direction. Acceptance: Submit fitted coefficients and post-fit residuals."}],"quiz":{"question":"檢查「區別倍率與局部變形」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Distinguish scale error from local distortion\", which conclusion is supported?","options":["提交擬合係數與扣除後殘差。","調一個平移量能消除全片倍率差。","徑向與切向向量代表同一誤差機制。"],"optionsEn":["Submit fitted coefficients and post-fit residuals.","One translation removes wafer-scale mismatch.","Radial and tangential vectors indicate the same mechanism."],"answer":0,"explanation":"假設倍率差 1 ppm、r=100 mm，徑向差 100 nm；與 1 µrad 旋轉量級相同但方向不同。 只報全片 RMS 無法區分可校正的倍率與局部缺陷。","explanationEn":"A hypothetical 1 ppm scale mismatch at r=100 mm gives 100 nm radial error, comparable in magnitude to 1 µrad rotation but different in direction. Whole-wafer RMS alone cannot distinguish correctable scale from local defects."}},{"id":"a106-v9-017","order":5,"sequence":17,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"prerequisiteIds":["a106-v9-016"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"計算接墊重疊與對位窗口","titleEn":"Calculate pad overlap and overlay window","objective":"報告 72% 並列仍需接觸電阻驗證。","objectiveEn":"Report 72% and retain contact-resistance verification.","instruction":"以兩個等大方形接墊作教學模型，逐次改變 dx、dy，計算重疊比例並標明模型不是原廠版圖。","instructionEn":"Use two equal square pads as a teaching model, sweep dx and dy, calculate overlap fraction and identify the layout as authored.","observation":"假設邊長 1 µm、dx=0.2 µm、dy=0.1 µm，重疊=(1−0.2)(1−0.1)=0.72 µm²，即 72%。","observationEn":"Hypothetical 1 µm squares with dx=0.2 µm and dy=0.1 µm overlap by (1−0.2)(1−0.1)=0.72 µm², or 72%.","failure":"以圓形接墊套用方形面積公式會得到錯誤窗口。","failureEn":"Applying the square formula to round pads gives an incorrect window.","check":"報告 72% 並列仍需接觸電阻驗證。","checkEn":"Report 72% and retain contact-resistance verification.","knowledge":[{"id":"a106-v9-017-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"重疊面積影響接觸機會，但電阻還受界面品質影響；幾何重疊不是完整電性驗證。","textEn":"Overlap affects contact opportunity, but resistance also depends on interface quality; geometry alone is not electrical validation.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"]},{"id":"a106-v9-017-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設邊長 1 µm、dx=0.2 µm、dy=0.1 µm，重疊=(1−0.2)(1−0.1)=0.72 µm²，即 72%。 驗收：報告 72% 並列仍需接觸電阻驗證。","textEn":"Hypothetical 1 µm squares with dx=0.2 µm and dy=0.1 µm overlap by (1−0.2)(1−0.1)=0.72 µm², or 72%. Acceptance: Report 72% and retain contact-resistance verification."}],"quiz":{"question":"檢查「計算接墊重疊與對位窗口」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Calculate pad overlap and overlay window\", which conclusion is supported?","options":["72% 重疊必然代表 72% 電性良率。","報告 72% 並列仍需接觸電阻驗證。","接墊放大可無限改善而沒有鄰點代價。"],"optionsEn":["72% overlap necessarily means 72% electrical yield.","Report 72% and retain contact-resistance verification.","Unlimited pad enlargement has no neighboring-pad penalty."],"answer":1,"explanation":"假設邊長 1 µm、dx=0.2 µm、dy=0.1 µm，重疊=(1−0.2)(1−0.1)=0.72 µm²，即 72%。 以圓形接墊套用方形面積公式會得到錯誤窗口。","explanationEn":"Hypothetical 1 µm squares with dx=0.2 µm and dy=0.1 µm overlap by (1−0.2)(1−0.1)=0.72 µm², or 72%. Applying the square formula to round pads gives an incorrect window."}},{"id":"a106-v9-018","order":6,"sequence":18,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9a-imecd2w"],"prerequisiteIds":["a106-v9-017"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"同時計算鄰點淨間距","titleEn":"Calculate neighboring-pad clearance","objective":"同圖標重疊和 0.7 µm 淨間距，另列電場評估。","objectiveEn":"Mark overlap and 0.7 µm clearance together and retain electric-field assessment.","instruction":"畫三個相鄰方形接墊，沿最危險方向平移上層，計算對目標與鄰點的間距。","instructionEn":"Draw three adjacent square pads, translate the upper layer in the critical direction and compute intended and neighbor clearances.","observation":"假設節距 2 µm、等寬 1 µm、偏移 0.3 µm，簡化同向幾何的鄰點最小邊距=2−1−0.3=0.7 µm。","observationEn":"For hypothetical 2 µm pitch, 1 µm equal widths and 0.3 µm shift, simplified directional neighbor clearance is 2−1−0.3=0.7 µm.","failure":"只最大化重疊可能消耗介電隔離餘裕。","failureEn":"Maximizing overlap alone can consume dielectric isolation margin.","check":"同圖標重疊和 0.7 µm 淨間距，另列電場評估。","checkEn":"Mark overlap and 0.7 µm clearance together and retain electric-field assessment.","knowledge":[{"id":"a106-v9-018-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"提升重疊和保留鄰近隔離是相互競爭的幾何需求，不能只檢查正確配對接點。","textEn":"Improving overlap competes with neighboring isolation; checking only intended pairs is insufficient.","sourceIds":["v6-hybrid-imec","v9a-imecd2w"]},{"id":"a106-v9-018-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設節距 2 µm、等寬 1 µm、偏移 0.3 µm，簡化同向幾何的鄰點最小邊距=2−1−0.3=0.7 µm。 驗收：同圖標重疊和 0.7 µm 淨間距，另列電場評估。","textEn":"For hypothetical 2 µm pitch, 1 µm equal widths and 0.3 µm shift, simplified directional neighbor clearance is 2−1−0.3=0.7 µm. Acceptance: Mark overlap and 0.7 µm clearance together and retain electric-field assessment."}],"quiz":{"question":"檢查「同時計算鄰點淨間距」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Calculate neighboring-pad clearance\", which conclusion is supported?","options":["只看目標重疊即可排除相鄰漏電。","0.7 µm 幾何間距直接證明所有電壓都安全。","同圖標重疊和 0.7 µm 淨間距，另列電場評估。"],"optionsEn":["Intended overlap alone rules out neighbor leakage.","A 0.7 µm gap guarantees isolation at every voltage.","Mark overlap and 0.7 µm clearance together and retain electric-field assessment."],"answer":2,"explanation":"假設節距 2 µm、等寬 1 µm、偏移 0.3 µm，簡化同向幾何的鄰點最小邊距=2−1−0.3=0.7 µm。 只最大化重疊可能消耗介電隔離餘裕。","explanationEn":"For hypothetical 2 µm pitch, 1 µm equal widths and 0.3 µm shift, simplified directional neighbor clearance is 2−1−0.3=0.7 µm. Maximizing overlap alone can consume dielectric isolation margin."}}]},{"id":"a106-v9-stage05","order":5,"sequence":5,"title":"表面形貌、污染與接合波","titleEn":"Topography, contamination and bond waves","description":"六項原創工程推算與判讀任務。算例皆為明示假設，需保留單位、參考面、模型範圍與驗收證據。","descriptionEn":"Six authored calculation and interpretation tasks. Examples are explicitly hypothetical; retain units, reference planes, model limits and acceptance evidence.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"enrichmentVersion":9,"steps":[{"id":"a106-v9-019","order":1,"sequence":19,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v9-018"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"區分粗糙度、凹陷與全片翹曲","titleEn":"Distinguish roughness, recess and wafer bow","objective":"為三種尺度各指定獨立指標與量測方法。","objectiveEn":"Assign independent metrics and methods to all three scales.","instruction":"為 AFM、輪廓或全片形貌各畫量測視窗，標明濾波及基準面，避免先濾掉欲檢查訊號。","instructionEn":"Draw measurement windows for AFM, profiling and wafer shape, specifying filters and reference planes without filtering away the target signal.","observation":"教學例：1 µm 視窗的 0.2 nm RMS 與全片 20 µm bow 可同時存在；兩者不矛盾，也不能互相替代。","observationEn":"Teaching example: 0.2 nm RMS over a 1 µm window can coexist with 20 µm whole-wafer bow; neither contradicts nor replaces the other.","failure":"小區域很平不代表整片能無缺陷接觸。","failureEn":"A locally smooth area does not guarantee defect-free whole-wafer contact.","check":"為三種尺度各指定獨立指標與量測方法。","checkEn":"Assign independent metrics and methods to all three scales.","knowledge":[{"id":"a106-v9-019-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"奈米級表面粗糙、局部 Cu 凹陷與全片翹曲分属不同空間尺度，單一 RMS 不能同時描述。","textEn":"Nanoscale roughness, local Cu recess and wafer bow occur at different spatial scales; one RMS cannot describe them all.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"]},{"id":"a106-v9-019-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學例：1 µm 視窗的 0.2 nm RMS 與全片 20 µm bow 可同時存在；兩者不矛盾，也不能互相替代。 驗收：為三種尺度各指定獨立指標與量測方法。","textEn":"Teaching example: 0.2 nm RMS over a 1 µm window can coexist with 20 µm whole-wafer bow; neither contradicts nor replaces the other. Acceptance: Assign independent metrics and methods to all three scales."}],"quiz":{"question":"檢查「區分粗糙度、凹陷與全片翹曲」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Distinguish roughness, recess and wafer bow\", which conclusion is supported?","options":["為三種尺度各指定獨立指標與量測方法。","AFM RMS 合格即證明全片翹曲合格。","去除所有低頻成分後仍可直接量 bow。"],"optionsEn":["Assign independent metrics and methods to all three scales.","Passing AFM RMS proves whole-wafer bow compliance.","Bow remains directly measurable after removing all low-frequency content."],"answer":0,"explanation":"教學例：1 µm 視窗的 0.2 nm RMS 與全片 20 µm bow 可同時存在；兩者不矛盾，也不能互相替代。 小區域很平不代表整片能無缺陷接觸。","explanationEn":"Teaching example: 0.2 nm RMS over a 1 µm window can coexist with 20 µm whole-wafer bow; neither contradicts nor replaces the other. A locally smooth area does not guarantee defect-free whole-wafer contact."}},{"id":"a106-v9-020","order":2,"sequence":20,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v9-019"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"建立銅凹陷分布而非單點值","titleEn":"Map copper recess rather than one point","objective":"呈現分布和最差點，門檻標為教學假設。","objectiveEn":"Show distribution and worst point, labeling the threshold hypothetical.","instruction":"對稀疏與密集接墊各取中心和邊緣掃描，保存原始剖面、平面扣除方法及異常值。","instructionEn":"Scan center and edge of sparse and dense pads and retain raw profiles, plane-removal method and outliers.","observation":"假設凹陷量 2、3、4 nm，平均 3 nm 不代表每點都是 3；若自訂窗口 2–3.5 nm，4 nm 點仍不符合。","observationEn":"Hypothetical recess values 2, 3 and 4 nm average 3 nm, but a 4 nm point fails an authored 2–3.5 nm window.","failure":"只以平均値放行會遮蔽局部過度凹陷。","failureEn":"Acceptance by average hides excessive local recess.","check":"呈現分布和最差點，門檻標為教學假設。","checkEn":"Show distribution and worst point, labeling the threshold hypothetical.","knowledge":[{"id":"a106-v9-020-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"凹陷是 Cu 相對周圍介電層的高度差，需一致基準面、材料辨識和掃描位置。","textEn":"Recess is copper height relative to surrounding dielectric and requires a consistent plane, material identification and scan location.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"]},{"id":"a106-v9-020-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設凹陷量 2、3、4 nm，平均 3 nm 不代表每點都是 3；若自訂窗口 2–3.5 nm，4 nm 點仍不符合。 驗收：呈現分布和最差點，門檻標為教學假設。","textEn":"Hypothetical recess values 2, 3 and 4 nm average 3 nm, but a 4 nm point fails an authored 2–3.5 nm window. Acceptance: Show distribution and worst point, labeling the threshold hypothetical."}],"quiz":{"question":"檢查「建立銅凹陷分布而非單點值」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Map copper recess rather than one point\", which conclusion is supported?","options":["平均 3 nm 即代表所有點合格。","呈現分布和最差點，門檻標為教學假設。","凹陷可忽略介電基準直接讀絕對高度。"],"optionsEn":["A 3 nm average means every point passes.","Show distribution and worst point, labeling the threshold hypothetical.","Recess can be read as absolute height without a dielectric reference."],"answer":1,"explanation":"假設凹陷量 2、3、4 nm，平均 3 nm 不代表每點都是 3；若自訂窗口 2–3.5 nm，4 nm 點仍不符合。 只以平均値放行會遮蔽局部過度凹陷。","explanationEn":"Hypothetical recess values 2, 3 and 4 nm average 3 nm, but a 4 nm point fails an authored 2–3.5 nm window. Acceptance by average hides excessive local recess."}},{"id":"a106-v9-021","order":3,"sequence":21,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v9-020"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"檢查圖形密度與 CMP 差異","titleEn":"Inspect pattern-density effects on CMP","objective":"提出有前後量測與副作用檢查的 dummy 試驗。","objectiveEn":"Propose a dummy-layout experiment with before/after data and side-effect checks.","instruction":"畫出相同晶粒內的稀疏、密集及 dummy 區，將高度差與密度圖疊合，控制量測尺度。","instructionEn":"Map sparse, dense and dummy regions on one die, overlay height differences and density, and control measurement scale.","observation":"教學假設兩區金屬密度 20% 和 60%，即使全片平均膜厚相同，也不能推定局部接墊高度相同。","observationEn":"Hypothetical 20% and 60% metal-density regions can share wafer-average thickness yet have different local pad heights.","failure":"增加 dummy 而不檢查電容、隔離和對位標記，可能引入其他問題。","failureEn":"Adding dummy metal without checking capacitance, isolation and marks may introduce other problems.","check":"提出有前後量測與副作用檢查的 dummy 試驗。","checkEn":"Propose a dummy-layout experiment with before/after data and side-effect checks.","knowledge":[{"id":"a106-v9-021-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"局部金屬密度與特徵尺寸改變拋光接觸條件，可能造成凹陷與侵蝕的不同趨勢。","textEn":"Local metal density and feature size change polishing contact conditions and can affect dishing and erosion differently.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"]},{"id":"a106-v9-021-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學假設兩區金屬密度 20% 和 60%，即使全片平均膜厚相同，也不能推定局部接墊高度相同。 驗收：提出有前後量測與副作用檢查的 dummy 試驗。","textEn":"Hypothetical 20% and 60% metal-density regions can share wafer-average thickness yet have different local pad heights. Acceptance: Propose a dummy-layout experiment with before/after data and side-effect checks."}],"quiz":{"question":"檢查「檢查圖形密度與 CMP 差異」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Inspect pattern-density effects on CMP\", which conclusion is supported?","options":["全片平均厚度等於局部平坦度。","dummy 只改機械性，永遠不影響電性。","提出有前後量測與副作用檢查的 dummy 試驗。"],"optionsEn":["Wafer-average thickness equals local planarity.","Dummy metal affects mechanics only and never electrical behavior.","Propose a dummy-layout experiment with before/after data and side-effect checks."],"answer":2,"explanation":"教學假設兩區金屬密度 20% 和 60%，即使全片平均膜厚相同，也不能推定局部接墊高度相同。 增加 dummy 而不檢查電容、隔離和對位標記，可能引入其他問題。","explanationEn":"Hypothetical 20% and 60% metal-density regions can share wafer-average thickness yet have different local pad heights. Adding dummy metal without checking capacitance, isolation and marks may introduce other problems."}},{"id":"a106-v9-022","order":4,"sequence":22,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v9-021"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"從污染密度估算無缺陷機率","titleEn":"Estimate defect-free probability from contamination","objective":"標出獨立、均勻、致命比例三項假設。","objectiveEn":"State independence, uniformity and fatal-fraction assumptions.","instruction":"選定有效接合面積，換算顆粒密度單位，再對密度與有效致命比例做敏感度分析。","instructionEn":"Choose effective bond area, convert particle-density units and sweep density and effective fatal fraction.","observation":"假設 D=0.01/mm²、A=100 mm²，P0=e⁻¹=36.79%；這不是所有顆粒皆致命的實測結論，只是模型假設。","observationEn":"Hypothetical D=0.01/mm² and A=100 mm² give P0=e⁻¹=36.79%; fatality of every particle is an assumed model, not measured evidence.","failure":"把顆粒計數直接轉電性良率而不辨粒徑位置，會過度簡化。","failureEn":"Converting particle count directly to electrical yield ignores size and location.","check":"標出獨立、均勻、致命比例三項假設。","checkEn":"State independence, uniformity and fatal-fraction assumptions.","knowledge":[{"id":"a106-v9-022-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"簡化 Poisson 模型 P0=exp(−DA) 假設缺陷獨立且均勻；群聚污染需用空間地圖檢查。","textEn":"The simplified Poisson model P0=exp(−DA) assumes independent uniform defects; clusters require spatial-map checks.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"]},{"id":"a106-v9-022-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 D=0.01/mm²、A=100 mm²，P0=e⁻¹=36.79%；這不是所有顆粒皆致命的實測結論，只是模型假設。 驗收：標出獨立、均勻、致命比例三項假設。","textEn":"Hypothetical D=0.01/mm² and A=100 mm² give P0=e⁻¹=36.79%; fatality of every particle is an assumed model, not measured evidence. Acceptance: State independence, uniformity and fatal-fraction assumptions."}],"quiz":{"question":"檢查「從污染密度估算無缺陷機率」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Estimate defect-free probability from contamination\", which conclusion is supported?","options":["標出獨立、均勻、致命比例三項假設。","P0=36.79% 是所有實際產品的已知良率。","群聚污染可不看地圖直接用同一模型。"],"optionsEn":["State independence, uniformity and fatal-fraction assumptions.","36.79% is established yield for every actual product.","Clustered contamination needs no map-based check."],"answer":0,"explanation":"假設 D=0.01/mm²、A=100 mm²，P0=e⁻¹=36.79%；這不是所有顆粒皆致命的實測結論，只是模型假設。 把顆粒計數直接轉電性良率而不辨粒徑位置，會過度簡化。","explanationEn":"Hypothetical D=0.01/mm² and A=100 mm² give P0=e⁻¹=36.79%; fatality of every particle is an assumed model, not measured evidence. Converting particle count directly to electrical yield ignores size and location."}},{"id":"a106-v9-023","order":5,"sequence":23,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v9-022"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"規劃表面等待時間實驗","titleEn":"Design a surface queue-time experiment","objective":"提交隨機化表、混淆因子與量測指標。","objectiveEn":"Submit randomization, confounders and response metrics.","instruction":"設短、中、長三組自訂等待時間，隨機化量測順序，記錄濕度、載具、清潔批次及接合後缺陷。","instructionEn":"Choose short, medium and long authored delays, randomize measurement order and log humidity, carriers, cleaning lot and post-bond defects.","observation":"教學設計每組 5 試片共 15 片，只是比較計畫；不能在未量測前宣稱已找到製程窗口。","observationEn":"A teaching design of five coupons per delay uses 15 samples; it is an experiment plan, not evidence of a validated process window.","failure":"把長等待組全放在同一天，可能將日期差誤認為等待效應。","failureEn":"Running all long-delay samples on one day confounds delay with day effects.","check":"提交隨機化表、混淆因子與量測指標。","checkEn":"Submit randomization, confounders and response metrics.","knowledge":[{"id":"a106-v9-023-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"清潔或活化後的表面會隨環境與等待時間演變；時間、搬運和批次必須分開控制。","textEn":"Surfaces evolve after cleaning or activation with environment and delay; time, handling and lot must be controlled separately.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"]},{"id":"a106-v9-023-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學設計每組 5 試片共 15 片，只是比較計畫；不能在未量測前宣稱已找到製程窗口。 驗收：提交隨機化表、混淆因子與量測指標。","textEn":"A teaching design of five coupons per delay uses 15 samples; it is an experiment plan, not evidence of a validated process window. Acceptance: Submit randomization, confounders and response metrics."}],"quiz":{"question":"檢查「規劃表面等待時間實驗」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Design a surface queue-time experiment\", which conclusion is supported?","options":["未取得結果即可宣稱最短等待時間已合格。","提交隨機化表、混淆因子與量測指標。","等待組與批次完全重合不影響推論。"],"optionsEn":["The shortest delay can be declared qualified before data exist.","Submit randomization, confounders and response metrics.","Perfect confounding of delay and lot does not affect inference."],"answer":1,"explanation":"教學設計每組 5 試片共 15 片，只是比較計畫；不能在未量測前宣稱已找到製程窗口。 把長等待組全放在同一天，可能將日期差誤認為等待效應。","explanationEn":"A teaching design of five coupons per delay uses 15 samples; it is an experiment plan, not evidence of a validated process window. Running all long-delay samples on one day confounds delay with day effects."}},{"id":"a106-v9-024","order":6,"sequence":24,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v6-hybrid-evg"],"prerequisiteIds":["a106-v9-023"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"判讀接合波前與未接合區域","titleEn":"Interpret bond-wave fronts and unbonded regions","objective":"聯合波前、空洞圖與電性結果判讀。","objectiveEn":"Interpret fronts, void maps and electrical results together.","instruction":"在原創時序圖標接觸起點、波前和邊緣排氣，將最終空洞位置與前段形貌疊合。","instructionEn":"Mark initiation, fronts and edge venting on an original time sequence, then overlay final voids with pre-bond shape.","observation":"教學例：同樣 2 s 完成的兩片，一片中央空洞、一片無可見空洞；相同總時間不能證明相同品質。","observationEn":"Teaching example: two wafers finish in 2 s, but one has a central void and the other no visible void; equal duration does not prove equal quality.","failure":"把波前到邊緣視為所有接點已導通，混淆機械接觸與電連接。","failureEn":"A front reaching the edge does not establish electrical continuity at every contact.","check":"聯合波前、空洞圖與電性結果判讀。","checkEn":"Interpret fronts, void maps and electrical results together.","knowledge":[{"id":"a106-v9-024-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"波前傳播受局部間隙、氣體逸出、表面能與形狀影響，波速不是唯一品質指標。","textEn":"Bond-wave propagation depends on gap, gas escape, surface energy and shape; speed alone is not quality.","sourceIds":["v6-hybrid-imec","v6-hybrid-evg"]},{"id":"a106-v9-024-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學例：同樣 2 s 完成的兩片，一片中央空洞、一片無可見空洞；相同總時間不能證明相同品質。 驗收：聯合波前、空洞圖與電性結果判讀。","textEn":"Teaching example: two wafers finish in 2 s, but one has a central void and the other no visible void; equal duration does not prove equal quality. Acceptance: Interpret fronts, void maps and electrical results together."}],"quiz":{"question":"檢查「判讀接合波前與未接合區域」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Interpret bond-wave fronts and unbonded regions\", which conclusion is supported?","options":["接合波快就代表接觸電阻一定低。","波前到邊緣即可省略電測。","聯合波前、空洞圖與電性結果判讀。"],"optionsEn":["A fast bond wave guarantees low contact resistance.","A front reaching the edge eliminates electrical tests.","Interpret fronts, void maps and electrical results together."],"answer":2,"explanation":"教學例：同樣 2 s 完成的兩片，一片中央空洞、一片無可見空洞；相同總時間不能證明相同品質。 把波前到邊緣視為所有接點已導通，混淆機械接觸與電連接。","explanationEn":"Teaching example: two wafers finish in 2 s, but one has a central void and the other no visible void; equal duration does not prove equal quality. A front reaching the edge does not establish electrical continuity at every contact."}}]},{"id":"a106-v9-stage06","order":6,"sequence":6,"title":"熱機相容與電性去嵌","titleEn":"Thermomechanical compatibility and electrical de-embedding","description":"六項原創工程推算與判讀任務。算例皆為明示假設，需保留單位、參考面、模型範圍與驗收證據。","descriptionEn":"Six authored calculation and interpretation tasks. Examples are explicitly hypothetical; retain units, reference planes, model limits and acceptance evidence.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"enrichmentVersion":9,"steps":[{"id":"a106-v9-025","order":1,"sequence":25,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"prerequisiteIds":["a106-v9-024"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"估算熱膨脹與銅凹陷閉合","titleEn":"Estimate expansion and recess closure","objective":"報告 1 nm 量級及自由膨脹假設的限制。","objectiveEn":"Report the 1 nm scale and limitations of free expansion.","instruction":"畫銅、介電與基板剖面，先算自由膨脹，再列出拘束、微結構和蠕變所需證據。","instructionEn":"Draw copper, dielectric and substrate, calculate free expansion and list evidence needed for constraint, microstructure and creep.","observation":"假設 Δα=10 ppm/K、h=1 µm、ΔT=100 K，差動伸長約 1 nm；不能因此保證任何 1 nm 凹陷皆完成接合。","observationEn":"Hypothetical Δα=10 ppm/K, h=1 µm and ΔT=100 K give about 1 nm differential expansion, not proof that every 1 nm recess bonds.","failure":"直接把自由膨脹等同界面接觸，會漏掉拘束與表面狀態。","failureEn":"Equating free expansion with interface contact ignores constraint and surface state.","check":"報告 1 nm 量級及自由膨脹假設的限制。","checkEn":"Report the 1 nm scale and limitations of free expansion.","knowledge":[{"id":"a106-v9-025-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"Δh≈Δα·h·ΔT 是自由膨脹的尺度估計；嵌入銅受拘束且可能塑性變形，不能當通用退火配方。","textEn":"Δh≈Δα·h·ΔT estimates free-expansion scale; embedded copper is constrained and may deform plastically, so it is not a general annealing recipe.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"]},{"id":"a106-v9-025-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 Δα=10 ppm/K、h=1 µm、ΔT=100 K，差動伸長約 1 nm；不能因此保證任何 1 nm 凹陷皆完成接合。 驗收：報告 1 nm 量級及自由膨脹假設的限制。","textEn":"Hypothetical Δα=10 ppm/K, h=1 µm and ΔT=100 K give about 1 nm differential expansion, not proof that every 1 nm recess bonds. Acceptance: Report the 1 nm scale and limitations of free expansion."}],"quiz":{"question":"檢查「估算熱膨脹與銅凹陷閉合」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Estimate expansion and recess closure\", which conclusion is supported?","options":["報告 1 nm 量級及自由膨脹假設的限制。","只憑此公式即可指定量產退火溫度。","所有材料都可忽略拘束自由膨脹。"],"optionsEn":["Report the 1 nm scale and limitations of free expansion.","This formula alone sets a production anneal temperature.","All materials expand freely without constraint."],"answer":0,"explanation":"假設 Δα=10 ppm/K、h=1 µm、ΔT=100 K，差動伸長約 1 nm；不能因此保證任何 1 nm 凹陷皆完成接合。 直接把自由膨脹等同界面接觸，會漏掉拘束與表面狀態。","explanationEn":"Hypothetical Δα=10 ppm/K, h=1 µm and ΔT=100 K give about 1 nm differential expansion, not proof that every 1 nm recess bonds. Equating free expansion with interface contact ignores constraint and surface state."}},{"id":"a106-v9-026","order":2,"sequence":26,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"prerequisiteIds":["a106-v9-025"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"建立熱歷程與材料相容性表","titleEn":"Build a thermal-history compatibility table","objective":"交付分層相容性表並標出需要實驗的界面。","objectiveEn":"Deliver a layer-by-layer table and flag interfaces requiring experiments.","instruction":"逐層列材料、既往熱歷程及尚未驗證的變化，分開升溫、停留和冷卻資料。","instructionEn":"List materials, prior thermal histories and unverified changes layer by layer, separating ramp, dwell and cooldown data.","observation":"教學例：兩個方案峰值相同但停留 10 和 100 min，擴散或反應程度一般不能假設相同；不自行替代原廠材料規格。","observationEn":"Teaching example: equal peaks with 10 versus 100 min dwell need not have equal diffusion or reaction; vendor material limits cannot be replaced by this example.","failure":"只核峰值溫度會忽略時間依賴與累積歷程。","failureEn":"Checking only the peak ignores time dependence and accumulated history.","check":"交付分層相容性表並標出需要實驗的界面。","checkEn":"Deliver a layer-by-layer table and flag interfaces requiring experiments.","knowledge":[{"id":"a106-v9-026-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"後接合熱處理同時影響金屬、介電、既有 BEOL 和元件；最高溫度不是唯一負載。","textEn":"Post-bond heating affects metal, dielectric, existing BEOL and devices; peak temperature is not the only load.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"]},{"id":"a106-v9-026-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學例：兩個方案峰值相同但停留 10 和 100 min，擴散或反應程度一般不能假設相同；不自行替代原廠材料規格。 驗收：交付分層相容性表並標出需要實驗的界面。","textEn":"Teaching example: equal peaks with 10 versus 100 min dwell need not have equal diffusion or reaction; vendor material limits cannot be replaced by this example. Acceptance: Deliver a layer-by-layer table and flag interfaces requiring experiments."}],"quiz":{"question":"檢查「建立熱歷程與材料相容性表」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Build a thermal-history compatibility table\", which conclusion is supported?","options":["峰值相同就代表任意停留時間等效。","交付分層相容性表並標出需要實驗的界面。","接合成功即可忽略原有元件特性漂移。"],"optionsEn":["Equal peaks make all dwell times equivalent.","Deliver a layer-by-layer table and flag interfaces requiring experiments.","Successful attachment makes prior device drift irrelevant."],"answer":1,"explanation":"教學例：兩個方案峰值相同但停留 10 和 100 min，擴散或反應程度一般不能假設相同；不自行替代原廠材料規格。 只核峰值溫度會忽略時間依賴與累積歷程。","explanationEn":"Teaching example: equal peaks with 10 versus 100 min dwell need not have equal diffusion or reaction; vendor material limits cannot be replaced by this example. Checking only the peak ignores time dependence and accumulated history."}},{"id":"a106-v9-027","order":3,"sequence":27,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"prerequisiteIds":["a106-v9-026"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"辨識破壞位置與接合能量","titleEn":"Identify fracture location and bond-energy evidence","objective":"提交荷重曲線、幾何及破面分類。","objectiveEn":"Submit load curves, geometry and fracture classification.","instruction":"畫裂紋路徑並記錄界面、介電或矽內破壞，對比相同幾何的試片，不混用剪切力與界面能。","instructionEn":"Map crack paths and identify interface, dielectric or silicon fracture, comparing identical geometries without mixing shear force and interface energy.","observation":"假設兩試片都在 20 N 破裂，一片界面分離、一片矽破裂；相同力不代表相同界面韌性。","observationEn":"Two hypothetical coupons fracture at 20 N, one at the interface and one in silicon; equal force does not imply equal interfacial toughness.","failure":"不記錄破面而只排列最大荷重，可能誤判改善方向。","failureEn":"Ranking peak load without fracture surfaces can misidentify improvement.","check":"提交荷重曲線、幾何及破面分類。","checkEn":"Submit load curves, geometry and fracture classification.","knowledge":[{"id":"a106-v9-027-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"機械測試數字只有配合幾何、載入方式與破面位置才可比較；高載荷可能由試片本體破裂決定。","textEn":"Mechanical values require geometry, loading and fracture location for comparison; high load may reflect substrate fracture rather than interface strength.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"]},{"id":"a106-v9-027-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設兩試片都在 20 N 破裂，一片界面分離、一片矽破裂；相同力不代表相同界面韌性。 驗收：提交荷重曲線、幾何及破面分類。","textEn":"Two hypothetical coupons fracture at 20 N, one at the interface and one in silicon; equal force does not imply equal interfacial toughness. Acceptance: Submit load curves, geometry and fracture classification."}],"quiz":{"question":"檢查「辨識破壞位置與接合能量」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Identify fracture location and bond-energy evidence\", which conclusion is supported?","options":["相同破壞力必然代表相同界面接合能。","矽本體破裂便能精確求出所有界面韌性。","提交荷重曲線、幾何及破面分類。"],"optionsEn":["Equal fracture force implies equal bond energy.","Silicon fracture precisely determines every interface toughness.","Submit load curves, geometry and fracture classification."],"answer":2,"explanation":"假設兩試片都在 20 N 破裂，一片界面分離、一片矽破裂；相同力不代表相同界面韌性。 不記錄破面而只排列最大荷重，可能誤判改善方向。","explanationEn":"Two hypothetical coupons fracture at 20 N, one at the interface and one in silicon; equal force does not imply equal interfacial toughness. Ranking peak load without fracture surfaces can misidentify improvement."}},{"id":"a106-v9-028","order":4,"sequence":28,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"prerequisiteIds":["a106-v9-027"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"以四端結構分離接點電阻","titleEn":"Separate contact resistance with four terminals","objective":"列單位、端點、反向電流檢查及不確定度。","objectiveEn":"List units, terminals, current-reversal check and uncertainty.","instruction":"畫電流端與高阻抗感測端，檢查電壓是否跨欲測接點，再改變電流方向檢查偏置。","instructionEn":"Draw current and high-impedance voltage terminals, verify the measured span and reverse current to check offset.","observation":"假設 I=10 mA、ΔV=50 µV，R=5 mΩ；若量測偏置 10 µV 未扣除，誤差相當於 1 mΩ。","observationEn":"Hypothetical I=10 mA and ΔV=50 µV give R=5 mΩ; an unremoved 10 µV offset corresponds to 1 mΩ error.","failure":"毫伏與微伏混用會造成千倍錯誤。","failureEn":"Confusing millivolts and microvolts creates a thousandfold error.","check":"列單位、端點、反向電流檢查及不確定度。","checkEn":"List units, terminals, current-reversal check and uncertainty.","knowledge":[{"id":"a106-v9-028-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"四端量測將施加電流與感測電壓分開以降低導線電阻影響，但仍需正確結構和寄生修正。","textEn":"Four-terminal measurement separates current and voltage paths to reduce lead resistance, but still requires valid structures and parasitic correction.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"]},{"id":"a106-v9-028-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 I=10 mA、ΔV=50 µV，R=5 mΩ；若量測偏置 10 µV 未扣除，誤差相當於 1 mΩ。 驗收：列單位、端點、反向電流檢查及不確定度。","textEn":"Hypothetical I=10 mA and ΔV=50 µV give R=5 mΩ; an unremoved 10 µV offset corresponds to 1 mΩ error. Acceptance: List units, terminals, current-reversal check and uncertainty."}],"quiz":{"question":"檢查「以四端結構分離接點電阻」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Separate contact resistance with four terminals\", which conclusion is supported?","options":["列單位、端點、反向電流檢查及不確定度。","四端法能自動消除所有偏置與版圖寄生。","50 µV 除以 10 mA 等於 5 Ω。"],"optionsEn":["List units, terminals, current-reversal check and uncertainty.","Four terminals automatically remove all offsets and layout parasitics.","50 µV divided by 10 mA is 5 Ω."],"answer":0,"explanation":"假設 I=10 mA、ΔV=50 µV，R=5 mΩ；若量測偏置 10 µV 未扣除，誤差相當於 1 mΩ。 毫伏與微伏混用會造成千倍錯誤。","explanationEn":"Hypothetical I=10 mA and ΔV=50 µV give R=5 mΩ; an unremoved 10 µV offset corresponds to 1 mΩ error. Confusing millivolts and microvolts creates a thousandfold error."}},{"id":"a106-v9-029","order":5,"sequence":29,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"prerequisiteIds":["a106-v9-028"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"從串鏈回推平均接點的限制","titleEn":"Understand limits of chain-derived contact averages","objective":"報告基線、接點數、平均與定位限制。","objectiveEn":"Report baseline, count, average and localization limits.","instruction":"列串鏈總電阻、參考走線和接點數，計算平均並設計不同長度鏈以檢查比例關係。","instructionEn":"List total resistance, reference wiring and contact count, calculate the average and use different chain lengths to test scaling.","observation":"假設 100 接點總 1.5 Ω、走線基線 1.0 Ω，平均接點 5 mΩ；可能仍混有少數高阻與多數低阻。","observationEn":"A hypothetical 100-contact chain at 1.5 Ω with 1.0 Ω wiring gives mean contact resistance 5 mΩ; high-resistance outliers may remain.","failure":"把平均值當每個接點精確值會遮蔽尾端分布。","failureEn":"Treating the mean as each exact contact value hides distribution tails.","check":"報告基線、接點數、平均與定位限制。","checkEn":"Report baseline, count, average and localization limits.","knowledge":[{"id":"a106-v9-029-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"串鏈含走線、轉接與大量接點；扣除基線後可估平均，但不能定位單一高阻接點。","textEn":"Chains include wiring, transitions and many contacts; baseline subtraction estimates an average but cannot locate one high-resistance contact.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"]},{"id":"a106-v9-029-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 100 接點總 1.5 Ω、走線基線 1.0 Ω，平均接點 5 mΩ；可能仍混有少數高阻與多數低阻。 驗收：報告基線、接點數、平均與定位限制。","textEn":"A hypothetical 100-contact chain at 1.5 Ω with 1.0 Ω wiring gives mean contact resistance 5 mΩ; high-resistance outliers may remain. Acceptance: Report baseline, count, average and localization limits."}],"quiz":{"question":"檢查「從串鏈回推平均接點的限制」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Understand limits of chain-derived contact averages\", which conclusion is supported?","options":["平均 5 mΩ 證明每個接點都是 5 mΩ。","報告基線、接點數、平均與定位限制。","可不扣走線直接除以接點數。"],"optionsEn":["A 5 mΩ average proves every contact is 5 mΩ.","Report baseline, count, average and localization limits.","Divide by contact count without removing wiring resistance."],"answer":1,"explanation":"假設 100 接點總 1.5 Ω、走線基線 1.0 Ω，平均接點 5 mΩ；可能仍混有少數高阻與多數低阻。 把平均值當每個接點精確值會遮蔽尾端分布。","explanationEn":"A hypothetical 100-contact chain at 1.5 Ω with 1.0 Ω wiring gives mean contact resistance 5 mΩ; high-resistance outliers may remain. Treating the mean as each exact contact value hides distribution tails."}},{"id":"a106-v9-030","order":6,"sequence":30,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"],"prerequisiteIds":["a106-v9-029"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"區分導通與介電隔離失效","titleEn":"Distinguish continuity from dielectric-isolation failure","objective":"分列導通、漏電與可靠度證據。","objectiveEn":"Separate continuity, leakage and reliability evidence.","instruction":"建立串鏈與梳狀隔離結構對照表，逐一預測開路、橋接及介電缺陷改變哪項測試。","instructionEn":"Map chain and comb-isolation structures and predict responses to opens, bridges and dielectric defects.","observation":"假設 1 V 下漏電 1 nA，等效靜態阻值 1 GΩ；這不等於已知擊穿電壓或時間依賴壽命。","observationEn":"Hypothetical leakage 1 nA at 1 V gives static equivalent resistance 1 GΩ, not breakdown voltage or time-dependent lifetime.","failure":"單一低壓漏電合格不能排除高場長時間劣化。","failureEn":"Passing one low-voltage leakage test does not exclude long-term high-field degradation.","check":"分列導通、漏電與可靠度證據。","checkEn":"Separate continuity, leakage and reliability evidence.","knowledge":[{"id":"a106-v9-030-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"接點低電阻和鄰近接點低漏電是不同驗證目標，必須有獨立結構與電壓條件。","textEn":"Low contact resistance and low neighbor leakage are separate targets requiring separate structures and voltage conditions.","sourceIds":["v6-hybrid-imec","v9deep-thermal-stress"]},{"id":"a106-v9-030-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 1 V 下漏電 1 nA，等效靜態阻值 1 GΩ；這不等於已知擊穿電壓或時間依賴壽命。 驗收：分列導通、漏電與可靠度證據。","textEn":"Hypothetical leakage 1 nA at 1 V gives static equivalent resistance 1 GΩ, not breakdown voltage or time-dependent lifetime. Acceptance: Separate continuity, leakage and reliability evidence."}],"quiz":{"question":"檢查「區分導通與介電隔離失效」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Distinguish continuity from dielectric-isolation failure\", which conclusion is supported?","options":["串鏈導通便能排除鄰點短路。","1 GΩ 靜態值可證明所有電壓無擊穿。","分列導通、漏電與可靠度證據。"],"optionsEn":["Chain continuity rules out neighbor shorts.","A static 1 GΩ value proves no breakdown at any voltage.","Separate continuity, leakage and reliability evidence."],"answer":2,"explanation":"假設 1 V 下漏電 1 nA，等效靜態阻值 1 GΩ；這不等於已知擊穿電壓或時間依賴壽命。 單一低壓漏電合格不能排除高場長時間劣化。","explanationEn":"Hypothetical leakage 1 nA at 1 V gives static equivalent resistance 1 GΩ, not breakdown voltage or time-dependent lifetime. Passing one low-voltage leakage test does not exclude long-term high-field degradation."}}]},{"id":"a106-v9-stage07","order":7,"sequence":7,"title":"統計、根因與資格交付","titleEn":"Statistics, root cause and qualification handoff","description":"六項原創工程推算與判讀任務。算例皆為明示假設，需保留單位、參考面、模型範圍與驗收證據。","descriptionEn":"Six authored calculation and interpretation tasks. Examples are explicitly hypothetical; retain units, reference planes, model limits and acceptance evidence.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"enrichmentVersion":9,"steps":[{"id":"a106-v9-031","order":1,"sequence":31,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"prerequisiteIds":["a106-v9-030"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"從接點失效率推算串鏈存活","titleEn":"Estimate chain survival from contact failures","objective":"保留獨立模型與群聚診斷的差異。","objectiveEn":"Distinguish the independence model from cluster diagnosis.","instruction":"掃描接點數 N 與單接點失效率 q，計算 (1−q)^N，再比較故障位置地圖。","instructionEn":"Sweep contact count N and failure probability q, calculate (1−q)^N and compare fault-location maps.","observation":"假設 q=0.001、N=1000，串鏈存活約 36.77%；單接點 99.9% 並不表示千接點鏈也是 99.9%。","observationEn":"Hypothetical q=0.001 and N=1000 give about 36.77% chain survival; 99.9% per contact is not 99.9% per thousand-contact chain.","failure":"將群聚缺陷視為獨立，會錯估不同鏈長的結果。","failureEn":"Treating clustered defects as independent misestimates chain-length effects.","check":"保留獨立模型與群聚診斷的差異。","checkEn":"Distinguish the independence model from cluster diagnosis.","knowledge":[{"id":"a106-v9-031-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"獨立接點存活相乘，長串鏈放大低機率缺陷；真實缺陷可能群聚，需另驗證。","textEn":"Independent contact survival multiplies and long chains amplify rare defects; real clustering requires separate validation.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"]},{"id":"a106-v9-031-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 q=0.001、N=1000，串鏈存活約 36.77%；單接點 99.9% 並不表示千接點鏈也是 99.9%。 驗收：保留獨立模型與群聚診斷的差異。","textEn":"Hypothetical q=0.001 and N=1000 give about 36.77% chain survival; 99.9% per contact is not 99.9% per thousand-contact chain. Acceptance: Distinguish the independence model from cluster diagnosis."}],"quiz":{"question":"檢查「從接點失效率推算串鏈存活」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Estimate chain survival from contact failures\", which conclusion is supported?","options":["保留獨立模型與群聚診斷的差異。","1000 接點鏈必然仍有 99.9% 良率。","長串鏈無法放大稀有接點缺陷。"],"optionsEn":["Distinguish the independence model from cluster diagnosis.","A 1000-contact chain must still yield 99.9%.","Long chains do not amplify rare contact defects."],"answer":0,"explanation":"假設 q=0.001、N=1000，串鏈存活約 36.77%；單接點 99.9% 並不表示千接點鏈也是 99.9%。 將群聚缺陷視為獨立，會錯估不同鏈長的結果。","explanationEn":"Hypothetical q=0.001 and N=1000 give about 36.77% chain survival; 99.9% per contact is not 99.9% per thousand-contact chain. Treating clustered defects as independent misestimates chain-length effects."}},{"id":"a106-v9-032","order":2,"sequence":32,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"prerequisiteIds":["a106-v9-031"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"量化零失效樣本的信賴界限","titleEn":"Quantify confidence after zero sample failures","objective":"明示樣本單位、數量、信賴度與相關性限制。","objectiveEn":"State sampling unit, count, confidence and correlation limits.","instruction":"分別以晶圓、晶粒或接點作抽樣單位，檢查是否同批相關，再計算可支持的上限。","instructionEn":"Choose wafer, die or contact as the sampling unit, inspect within-lot correlation and calculate the supported bound.","observation":"假設 300 個獨立試片零失效，95% 上限約 1%；不能宣稱失效率已低於 1 ppm。","observationEn":"With hypothetical 300 independent failure-free coupons, the approximate 95% upper bound is 1%, not evidence below 1 ppm.","failure":"把同片大量接點當完全獨立試片，可能誇大樣本資訊。","failureEn":"Treating many contacts on one wafer as independent coupons can exaggerate information.","check":"明示樣本單位、數量、信賴度與相關性限制。","checkEn":"State sampling unit, count, confidence and correlation limits.","knowledge":[{"id":"a106-v9-032-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"零失效只能界定上限；獨立二項模型下，95% 失效率上限約 3/n，樣本單位要明確。","textEn":"Zero failures only bounds the rate; under independent Bernoulli sampling the 95% upper bound is about 3/n and the sampling unit must be clear.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"]},{"id":"a106-v9-032-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"假設 300 個獨立試片零失效，95% 上限約 1%；不能宣稱失效率已低於 1 ppm。 驗收：明示樣本單位、數量、信賴度與相關性限制。","textEn":"With hypothetical 300 independent failure-free coupons, the approximate 95% upper bound is 1%, not evidence below 1 ppm. Acceptance: State sampling unit, count, confidence and correlation limits."}],"quiz":{"question":"檢查「量化零失效樣本的信賴界限」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Quantify confidence after zero sample failures\", which conclusion is supported?","options":["300 個零失效已證明小於 1 ppm。","明示樣本單位、數量、信賴度與相關性限制。","所有同片接點必然統計獨立。"],"optionsEn":["Three hundred zero-failure samples prove below 1 ppm.","State sampling unit, count, confidence and correlation limits.","All contacts on one wafer are necessarily independent."],"answer":1,"explanation":"假設 300 個獨立試片零失效，95% 上限約 1%；不能宣稱失效率已低於 1 ppm。 把同片大量接點當完全獨立試片，可能誇大樣本資訊。","explanationEn":"With hypothetical 300 independent failure-free coupons, the approximate 95% upper bound is 1%, not evidence below 1 ppm. Treating many contacts on one wafer as independent coupons can exaggerate information."}},{"id":"a106-v9-033","order":3,"sequence":33,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"prerequisiteIds":["a106-v9-032"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"整合上下片及接合後地圖","titleEn":"Merge upper, lower and post-bond maps","objective":"提交座標轉換與三標記殘差。","objectiveEn":"Submit transforms and three-mark residuals.","instruction":"以三個非共線且不對稱標記驗證轉換，疊合前段顆粒、對位殘差、空洞及電性地圖。","instructionEn":"Verify transforms with three asymmetric non-collinear marks and overlay particles, overlay residuals, voids and electrical maps.","observation":"教學例：上片圖左側缺陷經鏡射後可能對應成品右側；若直接疊圖，會錯誤宣稱缺陷不相關。","observationEn":"Teaching example: a defect on the upper map's left may become the assembled right after reflection; direct overlay could falsely suggest no correlation.","failure":"地圖方向錯誤會破壞根因分析而不易從圓形外觀察覺。","failureEn":"Wrong map orientation undermines root-cause analysis while wafer outlines still look correct.","check":"提交座標轉換與三標記殘差。","checkEn":"Submit transforms and three-mark residuals.","knowledge":[{"id":"a106-v9-033-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"晶圓面對面接合涉及鏡射、旋轉和座標原點；不同量測圖必須先轉為同一實體位置。","textEn":"Face-to-face bonding introduces reflection, rotation and origins; maps must be transformed to common physical coordinates.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"]},{"id":"a106-v9-033-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學例：上片圖左側缺陷經鏡射後可能對應成品右側；若直接疊圖，會錯誤宣稱缺陷不相關。 驗收：提交座標轉換與三標記殘差。","textEn":"Teaching example: a defect on the upper map's left may become the assembled right after reflection; direct overlay could falsely suggest no correlation. Acceptance: Submit transforms and three-mark residuals."}],"quiz":{"question":"檢查「整合上下片及接合後地圖」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Merge upper, lower and post-bond maps\", which conclusion is supported?","options":["圓形晶圓重合即代表所有座標正確。","鏡射可永遠以旋轉取代。","提交座標轉換與三標記殘差。"],"optionsEn":["Overlapping circles prove coordinate correctness.","Reflection can always be replaced by rotation.","Submit transforms and three-mark residuals."],"answer":2,"explanation":"教學例：上片圖左側缺陷經鏡射後可能對應成品右側；若直接疊圖，會錯誤宣稱缺陷不相關。 地圖方向錯誤會破壞根因分析而不易從圓形外觀察覺。","explanationEn":"Teaching example: a defect on the upper map's left may become the assembled right after reflection; direct overlay could falsely suggest no correlation. Wrong map orientation undermines root-cause analysis while wafer outlines still look correct."}},{"id":"a106-v9-034","order":4,"sequence":34,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"prerequisiteIds":["a106-v9-033"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"建立空洞與高阻的競爭假說","titleEn":"Build competing hypotheses for voids and high resistance","objective":"提交假說、辨識試驗及預期結果表。","objectiveEn":"Submit hypotheses, discriminating tests and expected results.","instruction":"列至少三個假說，為每個指定可支持及可否證的量測，先安排非破壞定位再選截面。","instructionEn":"List at least three hypotheses and supporting and falsifying measurements, using nondestructive localization before sectioning.","observation":"若空洞圖與高阻位置不重合，先查座標與檢測解析度，再考慮無可見空洞的電性機制。","observationEn":"If void and high-resistance maps do not coincide, first check coordinates and resolution before proposing electrically defective but visually bonded interfaces.","failure":"看到空洞就直接歸因清洗不足，會忽略形貌和困氣。","failureEn":"Attributing every void to poor cleaning ignores topography and trapped gas.","check":"提交假說、辨識試驗及預期結果表。","checkEn":"Submit hypotheses, discriminating tests and expected results.","knowledge":[{"id":"a106-v9-034-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"相同高阻可由未接合、污染、氧化或幾何錯位造成；單一影像通常不足以唯一決定根因。","textEn":"High resistance can arise from nonbonding, contamination, oxide or misalignment; one image rarely identifies a unique cause.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"]},{"id":"a106-v9-034-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"若空洞圖與高阻位置不重合，先查座標與檢測解析度，再考慮無可見空洞的電性機制。 驗收：提交假說、辨識試驗及預期結果表。","textEn":"If void and high-resistance maps do not coincide, first check coordinates and resolution before proposing electrically defective but visually bonded interfaces. Acceptance: Submit hypotheses, discriminating tests and expected results."}],"quiz":{"question":"檢查「建立空洞與高阻的競爭假說」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Build competing hypotheses for voids and high resistance\", which conclusion is supported?","options":["提交假說、辨識試驗及預期結果表。","任何空洞都只能由清洗不足造成。","沒有可見空洞必然表示電性完美。"],"optionsEn":["Submit hypotheses, discriminating tests and expected results.","Every void is caused only by poor cleaning.","No visible void guarantees perfect electrical behavior."],"answer":0,"explanation":"若空洞圖與高阻位置不重合，先查座標與檢測解析度，再考慮無可見空洞的電性機制。 看到空洞就直接歸因清洗不足，會忽略形貌和困氣。","explanationEn":"If void and high-resistance maps do not coincide, first check coordinates and resolution before proposing electrically defective but visually bonded interfaces. Attributing every void to poor cleaning ignores topography and trapped gas."}},{"id":"a106-v9-035","order":5,"sequence":35,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"prerequisiteIds":["a106-v9-034"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"分離加速試驗與使用壽命","titleEn":"Separate accelerated testing and service life","objective":"交付任務、機制、試驗與壽命推論界限。","objectiveEn":"Deliver mission, mechanism, test and limits of life inference.","instruction":"先定使用任務與失效判據，再選溫循、濕熱或電性應力；保留應力前後電阻、漏電和影像。","instructionEn":"Define mission and failure criterion before selecting cycling, humidity or electrical stress, retaining before/after resistance, leakage and images.","observation":"教學例：試片經 1000 次某溫循無失效，只能報該條件下的觀察；沒有模型與任務剖面不能換算十年壽命。","observationEn":"Teaching example: survival of 1000 cycles supports that observation only; ten-year life cannot be inferred without a model and mission profile.","failure":"以通過某次試驗宣稱所有環境永久可靠，是超出證據的推論。","failureEn":"Claiming permanent reliability in every environment from one test exceeds evidence.","check":"交付任務、機制、試驗與壽命推論界限。","checkEn":"Deliver mission, mechanism, test and limits of life inference.","knowledge":[{"id":"a106-v9-035-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"加速模型依賴失效機制；改變應力後若機制改變，單一加速因子便不適用。","textEn":"Acceleration models depend on failure mechanisms; one factor fails if stress changes the mechanism.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"]},{"id":"a106-v9-035-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"教學例：試片經 1000 次某溫循無失效，只能報該條件下的觀察；沒有模型與任務剖面不能換算十年壽命。 驗收：交付任務、機制、試驗與壽命推論界限。","textEn":"Teaching example: survival of 1000 cycles supports that observation only; ten-year life cannot be inferred without a model and mission profile. Acceptance: Deliver mission, mechanism, test and limits of life inference."}],"quiz":{"question":"檢查「分離加速試驗與使用壽命」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Separate accelerated testing and service life\", which conclusion is supported?","options":["1000 次任何溫循都等同十年使用。","交付任務、機制、試驗與壽命推論界限。","只要無失效就不需保留應力條件。"],"optionsEn":["Any 1000 thermal cycles equal ten years of service.","Deliver mission, mechanism, test and limits of life inference.","No failures removes the need to retain stress conditions."],"answer":1,"explanation":"教學例：試片經 1000 次某溫循無失效，只能報該條件下的觀察；沒有模型與任務剖面不能換算十年壽命。 以通過某次試驗宣稱所有環境永久可靠，是超出證據的推論。","explanationEn":"Teaching example: survival of 1000 cycles supports that observation only; ten-year life cannot be inferred without a model and mission profile. Claiming permanent reliability in every environment from one test exceeds evidence."}},{"id":"a106-v9-036","order":6,"sequence":36,"estimatedMinutes":25,"simulationOnly":true,"learningMode":"quantitative-design-review","evidenceStatus":"authored-educational-example","enrichmentVersion":9,"sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"],"prerequisiteIds":["a106-v9-035"],"sourceScope":"來源支持相關公開原理與研究背景；數值、判據、步序及選擇題為原創教學編排，並非原廠量產參數。","sourceScopeEn":"Sources support public principles and research context; numbers, criteria, sequence and quizzes are authored teaching work, not vendor production parameters.","title":"交付 W2W 資格證據封包","titleEn":"Deliver a W2W qualification-evidence package","objective":"另一人可重算例題並區分研究事實與未驗需求。","objectiveEn":"A peer can recompute examples and distinguish research facts from unverified requirements.","instruction":"整合上下片身份、旅行單、形貌、對位、機械與電性結果，逐需求列合格、未驗與不適用。","instructionEn":"Combine wafer identities, travelers, topography, overlay, mechanical and electrical results and mark each requirement passed, untested or inapplicable.","observation":"官方 2026 年 200 nm W2W 研究展示是有日期和試片範圍的里程碑；本課 1 µm 方墊算例不能被標為該流程複製。","observationEn":"The official 2026 200 nm W2W study is a dated test-vehicle milestone; this course's 1 µm square-pad examples are not reproductions of that flow.","failure":"把不同世代研究數字混成一份虛構量產配方會失去來源可追溯性。","failureEn":"Combining different research generations into a fictional production recipe destroys traceability.","check":"另一人可重算例題並區分研究事實與未驗需求。","checkEn":"A peer can recompute examples and distinguish research facts from unverified requirements.","knowledge":[{"id":"a106-v9-036-k1","title":"機制、公式與適用範圍","titleEn":"Mechanism, equation and validity","text":"研究節距紀錄、教學模擬與供應商資格需分開標示；交付應可追溯至晶圓、版圖與量測版本。","textEn":"Research pitch records, teaching simulations and supplier qualification must be separately labeled and traceable to wafers, layouts and measurement versions.","sourceIds":["v9deep-w2w-2026","pkb-tsmc-soic","v6-hybrid-imec"]},{"id":"a106-v9-036-k2","title":"原創算例與判讀","titleEn":"Authored worked example and interpretation","text":"官方 2026 年 200 nm W2W 研究展示是有日期和試片範圍的里程碑；本課 1 µm 方墊算例不能被標為該流程複製。 驗收：另一人可重算例題並區分研究事實與未驗需求。","textEn":"The official 2026 200 nm W2W study is a dated test-vehicle milestone; this course's 1 µm square-pad examples are not reproductions of that flow. Acceptance: A peer can recompute examples and distinguish research facts from unverified requirements."}],"quiz":{"question":"檢查「交付 W2W 資格證據封包」時，哪個判斷有完整工程依據？","questionEn":"When reviewing \"Deliver a W2W qualification-evidence package\", which conclusion is supported?","options":["課程完成即可代表原廠製造資格。","不同研究平台數字可直接混成共用配方。","另一人可重算例題並區分研究事實與未驗需求。"],"optionsEn":["Course completion grants vendor manufacturing qualification.","Numbers from different research platforms form one shared recipe.","A peer can recompute examples and distinguish research facts from unverified requirements."],"answer":2,"explanation":"官方 2026 年 200 nm W2W 研究展示是有日期和試片範圍的里程碑；本課 1 µm 方墊算例不能被標為該流程複製。 把不同世代研究數字混成一份虛構量產配方會失去來源可追溯性。","explanationEn":"The official 2026 200 nm W2W study is a dated test-vehicle milestone; this course's 1 µm square-pad examples are not reproductions of that flow. Combining different research generations into a fictional production recipe destroys traceability."}}]}],"scope":"公開原理的 36 項教學任務，包含自訂幾何、試算與實驗規劃；保留原 12 項進度 ID。研究里程碑、教學數字與量產資格明確區分，不提供專有配方。","scopeEn":"Thirty-six educational tasks in public principles with authored geometry, calculations and experiment plans, preserving the first twelve progress IDs. Research milestones, teaching numbers and production qualification remain distinct; no proprietary recipes are provided.","curriculumVersion":6,"enrichmentVersion":9,"subcategory":"pkg-joining","subcategoryTitle":"凸塊與精密接合","subcategoryTitleEn":"Bumps and precision bonding","photoId":"v8-wafer"}};
